const root=document.querySelector('#root'),key='skilltwin:v2:local',path=location.pathname.replace(/\/$/,'')||'/';
const read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}};
let state={name:'',course:'ai',goal:10,practice:{},days:[],rewards:{},...read(key,{})};
const save=()=>{try{localStorage.setItem(key,JSON.stringify(state));return true}catch{return false}};
// A deterministic, per-task ledger. Balances are derived, not incremented separately.
const rewardKey=(c,l)=>`${c.id}:${l.id}`;
const rewards=()=>Object.values(state.rewards||{});
const wallet=()=>{const earned=rewards().reduce((a,r)=>({coins:a.coins+5*(r.answers||[]).length+(r.finished?10:0)+(r.chest?15:0),gems:a.gems+(r.finished?2:0)+(r.chest?3:0),chests:a.chests+Number(!!r.chest),pending:a.pending+Number(!!r.finished&&!r.chest)}),{coins:0,gems:0,chests:0,pending:0});return {...earned,coins:Math.max(0,earned.coins+10*(state.dailyGifts?.length||0)-(state.shopSpent||0))}};
const rewardFor=(c,l)=>state.rewards?.[rewardKey(c,l)]||{answers:[],finished:false,chest:false};
function grant(c,l,kind,index){const k=rewardKey(c,l),old=rewardFor(c,l);let r={...old,answers:[...(old.answers||[])]};if(kind==='answer'){if(r.answers.includes(index)||old.finished)return false;r.answers.push(index)}else if(kind==='finish'){if(r.finished)return false;r.finished=true}else if(kind==='chest'){if(!r.finished||r.chest||!done(c,l))return false;r.chest=true}else return false;const prev=state.rewards;state.rewards={...prev,[k]:r};if(!save()){state.rewards=prev;return false}return true}
