const equipped=(type)=>type==='outfit'?(state.twinOutfit||'none'):type==='shoes'?(state.twinShoes||'none'):type==='hat'?(state.twinHat||'none'):(state.twinGlasses||'none');
const outfitOverlay=()=>{let h='';if(equipped('outfit')==='hoodie')h+='<path d="M61 96Q90 83 119 96L123 132L113 149H68L57 132Z" fill="#eee5ff" stroke="#ad91e6" stroke-width="3"/><path d="M78 100L90 111 102 100M86 111v12M94 111v12" stroke="#ac8edc" stroke-width="3" fill="none" stroke-linecap="round"/>';if(equipped('shoes')==='sneakers')h+='<path d="M58 162h29l-4 15H61q-11 0-3-15ZM93 162h29q9 15-3 15H97Z" fill="#fefefe" stroke="#8d79bb" stroke-width="3"/>';if(equipped('hat')==='cap')h+='<path d="M47 35Q51 5 91 6Q128 7 132 35L122 40H58Z" fill="#7959d9"/><path d="M68 37Q112 33 142 42Q128 53 91 48Z" fill="#6144b4"/>';if(equipped('glasses')==='glasses')h+='<g stroke="#322a47" stroke-width="3" fill="#30283f" fill-opacity=".70"><rect x="60" y="45" width="27" height="20" rx="9"/><rect x="93" y="45" width="27" height="20" rx="9"/><path d="M87 52h6"/></g>';return h};
