let ti=0;const twin=()=>{const id='bear'+(++ti);return `<svg viewBox="0 0 180 190" class="st-twin st-live-twin st-bear" role="img" aria-label="Твин — мультяшный мишка"><defs><radialGradient id="${id}" cx="30%" cy="18%" r="90%"><stop stop-color="${twinColor()}"/><stop offset="1" stop-color="${twinColor()}"/></radialGradient></defs><ellipse class="st-twin-shadow" cx="90" cy="180" rx="48" ry="7" fill="#5c4b8a" opacity=".13"/><g class="st-twin-living" fill="url(#${id})" stroke="#aaa5b8" stroke-width="1.2"><path class="st-twin-arm st-twin-left" d="M61 98Q42 98 36 125L32 145Q31 155 42 158L54 151 71 116Z"/><path class="st-twin-arm st-twin-right" d="M119 98Q138 98 144 125L148 145Q149 155 138 158L126 151 109 116Z"/><path d="M62 100Q53 114 58 143L65 153 60 168Q57 180 73 179L85 177 90 157 95 177Q110 182 120 175L115 153 122 143Q127 114 118 100Z"/><g class="st-twin-head"><circle cx="54" cy="27" r="20"/><circle cx="126" cy="27" r="20"/><circle cx="54" cy="27" r="10" fill="#eac9d9" stroke="none"/><circle cx="126" cy="27" r="10" fill="#eac9d9" stroke="none"/><circle cx="90" cy="63" r="49"/><g fill="#342f45" stroke="none" class="st-twin-eyes"><ellipse cx="73" cy="59" rx="5" ry="7"/><ellipse cx="107" cy="59" rx="5" ry="7"/></g><ellipse cx="90" cy="82" rx="22" ry="15" fill="#fffaf7" stroke="none"/><path d="M83 76q7-7 14 0q-2 7-7 8q-6-1-7-8Z" fill="#3b3545" stroke="none"/><path d="M90 84v5m0 0q-7 8-12 0m12 0q7 8 12 0" stroke="#534453" stroke-width="2.2" fill="none" stroke-linecap="round"/></g>${outfitOverlay()}</g></svg>`};
const audioIcon=muted=>`<svg width="21" height="21" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M11 5 6 9H3v6h3l5 4Z"/>${muted?'<path d="m16 9 5 6m0-6-5 6"/>':'<path d="M15 9a4 4 0 0 1 0 6m3-9a8 8 0 0 1 0 12"/>'}</svg>`;
const audioControls=()=>{const a=audioSettings();return `<div class="st-audio" data-audio-ui><button type="button" class="st-audio-toggle" id="st-audio-toggle" aria-label="Настройки звука" aria-expanded="false">${audioIcon(!a.effects&&!a.music||a.volume===0)}</button><div class="st-audio-panel" id="st-audio-panel" hidden><div class="st-audio-heading"><div><small>АТМОСФЕРА</small><h3>Звук и музыка</h3></div><button type="button" class="st-audio-close" id="st-audio-close" aria-label="Закрыть настройки">×</button></div><label><span><b>Звуки игры</b><small>Клики, ответы и награды</small></span><input type="checkbox" id="st-effects" ${a.effects?'checked':''}></label><label><span><b>Фоновая музыка</b><small>Спокойная мелодия</small></span><input type="checkbox" id="st-music" ${a.music?'checked':''}></label><label class="st-volume-label"><span><b>Громкость</b><small id="st-volume-value">${Math.round(a.volume*100)}%</small></span><input type="range" min="0" max="100" value="${Math.round(a.volume*100)}" id="st-volume" aria-label="Громкость"></label><button type="button" class="st-outline" id="st-sound-test">Послушать звук сундука</button><small class="st-audio-tip">Звук включается после нажатия на экран.</small></div></div>`};
function bindAudio(){const panel=document.querySelector('#st-audio-panel'),toggle=document.querySelector('#st-audio-toggle');if(!panel||!toggle)return;const open=v=>{panel.hidden=!v;toggle.setAttribute('aria-expanded',String(v))};const update=()=>{const a=audioSettings();toggle.innerHTML=audioIcon(!a.effects&&!a.music||a.volume===0);document.querySelector('#st-sound-test').disabled=!a.effects||a.volume===0};toggle.onclick=()=>open(panel.hidden);document.querySelector('#st-audio-close').onclick=()=>open(false);document.querySelector('#st-effects').onchange=e=>{setAudio({effects:e.target.checked});update();if(e.target.checked)sound('click')};document.querySelector('#st-music').onchange=e=>{setAudio({music:e.target.checked});update()};document.querySelector('#st-volume').oninput=e=>{setAudio({volume:Number(e.target.value)/100});document.querySelector('#st-volume-value').textContent=e.target.value+'%';update()};document.querySelector('#st-sound-test').onclick=()=>sound('chest');update()}

const course=()=>courses.find(c=>c.id===state.course)||courses[0],list=c=>c.modules.flatMap(m=>m.lessons),ai=()=>read('skilltwin:v1:progress',{}),tracks=()=>read('skilltwin:v1:courses',{}).enrollments||{};
const done=(c,l)=>c.legacy?(ai().completed||[]).includes(+l.id):Boolean(tracks()[c.id]?.lessons?.[l.id]?.completedAt),href=(c,l)=>c.legacy?`/lesson/${l.id}`:`/courses/${c.id}/lesson/${l.id}`;
const completed=()=>courses.reduce((s,c)=>s+list(c).filter(l=>done(c,l)).length,0),xp=()=>completed()*20+Object.values(state.practice).reduce((s,x)=>s+(Number(x.best)||0)*5,0);
const day=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,days=()=>new Set([...(ai().activityDates||[]).map(x=>String(x).slice(0,10)),...state.days,...Object.values(tracks()).flatMap(e=>Object.values(e.lessons||{}).map(l=>l.completedAt?.slice(0,10)).filter(Boolean))]);
function streak(){const a=days(),d=new Date();if(!a.has(day(d)))d.setDate(d.getDate()-1);let n=0;while(a.has(day(d))){n++;d.setDate(d.getDate()-1)}return n}
const nav=[['learn','Обучение','/learn'],['courses','Курсы','/courses'],['practice','Тренировка','/quick'],['twin','Мой Твин','/companion'],['profile','Профиль','/profile']],active=path==='/profile'||path==='/progress'||path==='/dashboard'?'profile':path==='/quick'||path==='/practice'?'practice':path==='/courses'?'courses':path==='/companion'||path==='/mentor'?'twin':'learn';
const navHTML=()=>nav.map(([i,t,h])=>`<a class="st-nav ${i===active?'on':''}" href="${h}">${icon(i)}<span>${t}</span></a>`).join('');
function shell(content,aside=''){root.innerHTML=`<div class="st-app"><aside class="st-sidebar"><a class="st-logo" href="/learn"><span class="st-mark">S.</span><span>skilltwin<span class="st-dot">.</span><small>ACADEMY</small></span></a><nav>${navHTML()}</nav><div class="st-sidebar-end"><span class="st-tag">BETA 3.0</span><p>Учись делать, а не просто смотреть.</p><a href="mailto:skill-twin@proton.me">Написать нам · skill-twin@proton.me</a><a href="/?classic=1">Архив старой версии ↗</a></div></aside><div class="st-main"><header class="st-top"><a href="/learn" class="st-mobile-logo">skilltwin<span>.</span></a><span class="st-top-label">ТВОЁ ПРОСТРАНСТВО РОСТА</span><div class="st-top-right"><div class="st-stat st-fire">${icon('flame',21)} <b>${streak()}</b><small>дн.</small></div><div class="st-stat st-electric">${icon('practice',21)} <b>${xp()}</b><small>XP</small></div>${walletHTML()}${audioControls()}<a href="/account" class="st-avatar" aria-label="Профиль">${esc((state.name||'S').slice(0,1).toUpperCase())}</a></div></header><div class="st-content ${aside?'has-aside':''}"><main>${content}</main>${aside?`<aside class="st-right">${aside}</aside>`:''}</div></div><nav class="st-bottom">${navHTML()}</nav></div>`;bindAudio();document.title='SkillTwin — '+(active==='profile'?'Профиль':active==='practice'?'Тренировка':'Твой путь обучения')}
const picker=()=>`<label class="st-picker"><span>НАПРАВЛЕНИЕ</span><select id="st-course" aria-label="Выбрать курс">${courses.map(x=>`<option value="${x.id}" ${x.id===course().id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></label>`;
function home(){const c=course(),all=list(c),num=all.filter(l=>done(c,l)).length,next=all.find(l=>!done(c,l));let ix=0;
const modules=c.modules.map((m,mi)=>`<section class="st-module"><header class="st-module-head" style="--world-h:${(worldTheme(c.id)[0]+mi*32)%360}"><span>РАЗДЕЛ ${String(mi+1).padStart(2,'0')}</span><h2>${esc(m.title)}</h2><small>${m.lessons.filter(l=>done(c,l)).length} / ${m.lessons.length} уроков</small></header><div class="st-path">${m.lessons.map(l=>{let i=ix++,d=done(c,l),n=l.id===next?.id;return `<div class="st-node-row" style="--offset:${[0,44,0,-44][i%4]}px"><a href="${href(c,l)}" class="st-node ${d?'done':n?'current':'later'}" aria-label="${esc(l.title)} — ${d?'пройден':n?'следующий урок':'доступен'}">${icon(d?'check':n?'play':'learn',27)}</a><div class="st-node-label">${n?'<span class="st-now">ДАЛЬШЕ</span>':''}<strong>${esc(l.title)}</strong><small>${l.minutes} мин · ${d?'Пройден':n?'Начать урок':'Урок '+(i+1)}</small></div></div>`}).join('')}</div></section>`).join('');
const side=`<div class="st-card st-buddy"><span class="st-eyebrow">ТВОЙ ПАРТНЁР</span>${twin()}<h3>Привет${state.name?', '+esc(state.name):''}!</h3><p>${esc(talk(1,'sidebar-greeting'))}</p><a class="st-outline" href="/companion">Настроить Твина ${icon('arrow',16)}</a><a class="st-text-link" href="/shop">Магазин одежды →</a></div><div class="st-card"><span class="st-eyebrow">ЕЖЕДНЕВНАЯ ЦЕЛЬ</span><h3>${state.goal} минут в день</h3><p>${days().has(day(new Date()))?'Сегодня уже был учебный шаг!':'Начни с одного небольшого задания.'}</p><a href="/quick" class="st-text-link">Быстрая тренировка →</a></div><div class="st-card"><span class="st-eyebrow">ТВОЙ УРОВЕНЬ</span><h3>Уровень ${Math.floor(xp()/100)+1}</h3><div class="st-meter"><i style="width:${xp()%100}%"></i></div><p>${xp()%100}/100 XP до нового уровня</p></div>`;
shell(`<div class="st-intro"><div><span class="st-eyebrow">ОБУЧЕНИЕ / 01</span><h1>${state.name?'Продолжай, '+esc(state.name)+'!':'Твой путь к новым навыкам.'}</h1><p>Маленькие уроки. Большие возможности.</p></div>${picker()}</div><section class="st-hero st-world-hero" style="--world-h:${worldTheme(c.id)[0]}"><div><span class="st-hero-tag">ТВОЯ ТРАЕКТОРИЯ</span><h2>${esc(c.title)}</h2><p>${esc(c.description)}</p><div class="st-hero-progress"><div class="st-meter"><i style="width:${num/all.length*100}%"></i></div><b>${num}/${all.length} уроков</b></div><a class="st-button st-white" href="${next?href(c,next):'/courses'}">${next?(num?'Продолжить':'Начать обучение'):'Выбрать другой курс'} ${icon('arrow',19)}</a></div><div class="st-hero-art">${worldArt(c.id,c.symbol)}</div></section><div class="st-path-title"><h2>Учебная карта</h2><span>${all.length} уроков · ${c.modules.length} раздела</span></div>${modules}<div class="st-finish">${icon('flag',32)}<h3>Финиш курса</h3><p>${esc(c.outcome)}</p></div>`,side);document.querySelector('#st-course').onchange=e=>{state.course=e.target.value;save();home()}}
function shop(){const items=[...twinPalette.map(c=>({...c,type:'color',icon:'●'})),...twinClothes];const currentCoins=wallet().coins;
 const card=item=>{const owned=ownedItem(item.id),equippedNow=item.type==='color'?(state.twinColor||'charcoal')===item.id:equipped(item.type)===item.id;return `<article class="st-shop-card"><div class="st-shop-icon" ${item.type==='color'?`style="background:${item.color}"`:''}>${item.type==='color'?'':esc(item.icon)}</div><div><h3>${esc(item.name)}</h3><p>${item.type==='color'?'Цвет Твина':item.type==='outfit'?'Одежда':item.type==='shoes'?'Обувь':item.type==='hat'?'Головной убор':'Аксессуар'}</p></div><button class="${equippedNow?'st-outline':'st-button'}" data-buy="${item.id}" ${equippedNow?'disabled':''}>${equippedNow?'Надето':owned?'Надеть':item.price+' монет'}</button></article>`};
 shell(`<span class="st-eyebrow">TWIN SHOP · ИГРОВАЯ ВАЛЮТА</span><h1>Магазин Твина</h1><p class="st-lead">Меняй цвет, одежду и аксессуары. Всё покупается за монеты из уроков — реальные деньги не нужны.</p><div class="st-card st-shop-hero"><div>${twin()}<p>Твой стиль — твои правила.</p></div><div><h2>Твой баланс</h2>${walletHTML()}<p>Получай монеты за ответы, уроки и сундуки.</p><a href="/learn" class="st-outline">Заработать монеты →</a></div></div><div class="st-shop-head"><h2>Ежедневный подарок</h2><p>+10 монет раз в день за посещение магазина.</p><button id="st-daily-gift" class="st-button" ${dailyGiftReady()?'':'disabled'}>${dailyGiftReady()?'Забрать +10 монет':'Сегодня уже получено'}</button></div><h2>Цвета</h2><div class="st-shop-grid">${items.filter(x=>x.type==='color').map(card).join('')}</div><h2>Одежда и аксессуары</h2><div class="st-shop-grid">${items.filter(x=>x.type!=='color').map(card).join('')}</div><p id="st-shop-message" class="st-notice" role="status"></p><a href="/companion" class="st-outline">Вернуться в студию Твина →</a>`);
 document.querySelector('#st-daily-gift')?.addEventListener('click',()=>{if(!dailyGiftReady())return;const prev=state.dailyGifts;state.dailyGifts=[...(prev||[]),day(new Date())];if(!save()){state.dailyGifts=prev;return}sound('coin');shop()});
 document.querySelectorAll('[data-buy]').forEach(b=>b.onclick=()=>{const item=items.find(x=>x.id===b.dataset.buy);if(!item)return;const owned=ownedItem(item.id);if(!owned&&wallet().coins<item.price){document.querySelector('#st-shop-message').textContent='Пока не хватает монет. Пройди урок или открой сундук.';return}const previous={shopOwned:state.shopOwned,shopSpent:state.shopSpent,twinColor:state.twinColor,twinOutfit:state.twinOutfit,twinShoes:state.twinShoes,twinHat:state.twinHat,twinGlasses:state.twinGlasses};if(!owned){state.shopOwned=[...(state.shopOwned||[]),item.id];state.shopSpent=(state.shopSpent||0)+item.price}if(item.type==='color')state.twinColor=item.id;else if(item.type==='outfit')state.twinOutfit=item.id;else if(item.type==='shoes')state.twinShoes=item.id;else if(item.type==='hat')state.twinHat=item.id;else state.twinGlasses=item.id;if(!save()){Object.assign(state,previous);document.querySelector('#st-shop-message').textContent='Не удалось сохранить покупку.';return}sound(owned?'click':'coin');shop()})}

function profile(){shell(`<span class="st-eyebrow">ЛИЧНОЕ ПРОСТРАНСТВО</span><h1>Твой профиль</h1><p class="st-lead">Настрой SkillTwin под себя.</p><div class="st-card st-profile"><div class="st-profile-top">${twin()}<div><h2>${esc(state.name||'Новый ученик')}</h2><p>Уровень ${Math.floor(xp()/100)+1} · ${xp()} XP · ${completed()} уроков</p></div></div><div class="st-wallet-panel">${walletHTML()}<p>Открыто сундуков: ${wallet().chests}</p></div>${wallet().pending?`<div class="st-notice"><b>Неоткрытые сундуки: ${wallet().pending}</b>${courses.flatMap(c=>list(c).filter(l=>rewardFor(c,l).finished&&!rewardFor(c,l).chest&&done(c,l)).map(l=>`<p><a class="st-text-link" href="${href(c,l)}">${esc(l.title)} →</a></p>`)).join('')}</div>`:''}<form id="st-profile-form"><label>Как к тебе обращаться?<input name="name" maxlength="40" required placeholder="Имя или ник" value="${esc(state.name)}" autocomplete="nickname"></label><label>Ежедневная цель<select name="goal">${[5,10,15,20].map(g=>`<option value="${g}" ${state.goal===g?'selected':''}>${g} минут</option>`).join('')}</select></label>${picker()}<button class="st-button" type="submit">Сохранить профиль ${icon('check',20)}</button><p id="st-message" role="status"></p></form><p class="st-notice">${cloudState().user?'Аккаунт подключён. Проверь статус синхронизации в настройках аккаунта.':'Гостевой режим: прогресс хранится в этом браузере.'}</p><a class="st-button" href="/account">${cloudState().user?'Настройки аккаунта':'Войти / Создать аккаунт'}</a></div><a class="st-outline" href="/progress">Подробная статистика →</a><div class="st-card st-achievements"><h2>Твои достижения</h2><div class="st-achievement-list"><span class="${completed()>0?'earned':''}">★ Первый урок</span><span class="${wallet().chests>0?'earned':''}">◆ Первый сундук</span><span class="${completed()>=5?'earned':''}">⚡ Пять уроков</span></div></div><div class="st-profile-links"><a class="st-outline" href="/shop">Магазин Твина →</a><a class="st-outline" href="mailto:skill-twin@proton.me">Поддержка: skill-twin@proton.me</a><a class="st-outline" href="/practice">Мои практические работы</a><a class="st-outline" href="/mentor">Наставник</a><a class="st-text-link" href="/?classic=1">Архив старой версии (дополнительные инструменты)</a></div>`);const form=document.querySelector('#st-profile-form');form.onsubmit=e=>{e.preventDefault();const f=new FormData(form),name=String(f.get('name')).trim();if(!name){document.querySelector('#st-message').textContent='Введите имя.';return}state.name=name;state.goal=Number(f.get('goal'));state.course=document.querySelector('#st-course').value;const ok=save();document.querySelector('#st-message').textContent=ok?'Профиль сохранён.':'Не удалось сохранить профиль.';if(ok){document.querySelector('.st-profile-top h2').textContent=state.name;document.querySelector('.st-avatar').textContent=state.name[0].toUpperCase()}}}
let session=null;
function quick(){const c=course(),all=list(c),suggested=all.find(l=>!done(c,l)&&l.quiz.length)||all.find(l=>l.quiz.length);if(!session&&suggested)session={lesson:suggested,step:0,answer:-1,checked:false,score:0};if(!session){shell('<h1>Тренировка</h1><p>Для курса пока нет коротких заданий.</p><a href="/learn">Вернуться к карте</a>');return}const {lesson,step,answer,checked,score}=session,q=lesson.quiz[step],total=lesson.quiz.length;
let body=`<div class="st-quick-head"><a class="st-back" href="/learn">← Карта</a><span>БЫСТРАЯ ТРЕНИРОВКА</span><span>${Math.min(step+1,total)}/${total}</span></div><div class="st-meter st-quick-meter"><i style="width:${step/total*100}%"></i></div>`;
if(q){body+=`<div class="st-card st-quiz"><span class="st-eyebrow">${esc(c.title)} · ${esc(lesson.title)}</span><div class="st-quiz-twin ${checked?(answer===q.correct?'cheer':'think'):'think'}">${twin()}<p>${esc(talk(checked?(answer===q.correct?3:4):2,`quick-${c.id}-${lesson.id}-${step}-${checked}`))}</p></div><h1>${esc(q.question)}</h1><div class="st-options">${q.options.map((o,i)=>`<button class="st-option ${answer===i?'chosen':''} ${checked&&i===q.correct?'correct':''} ${checked&&answer===i&&i!==q.correct?'wrong':''}" data-option="${i}" ${checked?'disabled':''}><span>${String.fromCharCode(65+i)}</span>${esc(o)}</button>`).join('')}</div>${checked?`<div class="st-feedback ${answer===q.correct?'good':'bad'}"><b>${esc(talk(answer===q.correct?3:4))}</b><p>${esc(q.explanation)}</p></div><button class="st-button" id="st-next">Продолжить ${icon('arrow',19)}</button>`:`<button class="st-button" id="st-check" ${answer<0?'disabled':''}>Проверить ответ ${icon('check',19)}</button>`}</div>`}else{body+=`<div class="st-card st-results">${icon('star',52)}<h1>Тренировка завершена!</h1><p>${score} из ${total} правильных ответов</p><h2>+${session.earned||0} XP</h2><p>Тренировка не заменяет выполнение полного урока.</p><a class="st-button" href="${href(c,lesson)}">Открыть полный урок ${icon('arrow',18)}</a><button class="st-outline" id="st-repeat">Повторить</button><a href="/learn">Вернуться к карте</a></div>`}shell(`<div class="st-quick">${body}</div>`);document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{session.answer=Number(b.dataset.option);quick()});document.querySelector('#st-check')?.addEventListener('click',()=>{if(session.answer<0||session.checked)return;session.checked=true;sound(session.answer===q.correct?'correct':'wrong');if(session.answer===q.correct)session.score++;quick()});document.querySelector('#st-next')?.addEventListener('click',()=>{session.step++;session.checked=false;session.answer=-1;if(session.step===total){sound('finish');const k=c.id+':'+lesson.id,old=state.practice[k]?.best||0,best=Math.max(old,session.score);session.earned=(best-old)*5;state.practice[k]={best,total};const d=day(new Date());if(!state.days.includes(d))state.days.push(d);save()}quick()});document.querySelector('#st-repeat')?.addEventListener('click',()=>{session=null;quick()})}

