 shell(`<div class="st-intro"><div><span class="st-eyebrow">КАТАЛОГ НАВЫКОВ</span><h1>Выбери своё направление</h1><p>${baseItems.length} доступных курсов · ${lessonsTotal} уроков · новые языки в подготовке.</p></div></div><div class="st-filter st-filter-catalog"><input id="catalog-search" type="search" placeholder="Найти курс или язык" aria-label="Поиск курсов"><div class="st-filter-tabs" id="catalog-tabs">${groups.map((g,idx)=>`<button type="button" class="st-chip" data-filter-group="${esc(g)}" aria-pressed="${idx===0?'true':'false'}">${esc(g)}</button>`).join('')}</div></div><div id="catalog-sections"></div>`);
 const searchInput=document.querySelector('#catalog-search');
 const sections=document.querySelector('#catalog-sections');
 let currentGroup='Все';
 const card=item=>`<article class="st-card st-course-card ${item.status==='soon'?'is-soon':''}" data-search="${esc(item.search)}">${worldArt(item.id,item.symbol)}<div class="st-course-meta"><span class="st-tag">${esc(item.group)}</span><span class="st-tag">${esc(item.level)}</span>${item.status==='soon'?'<span class="st-tag st-tag-soon">Скоро</span>':''}</div><h2>${esc(item.title)}</h2><p>${esc(item.description)}</p>${item.outcome?`<details class="st-world-outcome"><summary>Что создашь к финалу</summary><p>${esc(item.outcome)}</p></details>`:''}${item.status==='live'?`<div class="st-meter"><i style="width:${item.progress/Math.max(1,item.lessons)*100}%"></i></div><p>${item.progress} / ${item.lessons} уроков</p><div class="st-course-actions"><button class="st-button" data-course="${esc(item.id)}">${item.action} ${icon('arrow',18)}</button></div>`:`<div class="st-soon-note"><b>${item.duration}</b><span>Добавим этот язык в одном из следующих апдейтов.</span></div>`}</article>`;
 const renderCatalog=()=>{const query=searchInput.value.toLowerCase().trim();const visible=items.filter(item=>(currentGroup==='Все'||item.group===currentGroup)&&(!query||item.search.includes(query)));const targetGroups=(currentGroup==='Все'?catalogOrder:[currentGroup]).filter(group=>visible.some(item=>item.group===group));sections.innerHTML=targetGroups.length?targetGroups.map(group=>{const groupItems=visible.filter(item=>item.group===group);return groupItems.length?`<section class="st-catalog-section"><div class="st-catalog-title"><h2>${esc(group)}</h2><span>${groupItems.length} ${groupItems.length===1?'курс':'курса'}</span></div><div class="st-catalog">${groupItems.map(card).join('')}</div></section>`:''}).join(''):'<div class="st-card"><h2>Ничего не найдено</h2><p>Попробуй другой запрос или выбери другую категорию.</p></div>';
 document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>chooseCourse(b.dataset.course));
 };
 document.querySelectorAll('[data-filter-group]').forEach(btn=>btn.onclick=()=>{currentGroup=btn.dataset.filterGroup;document.querySelectorAll('[data-filter-group]').forEach(x=>x.setAttribute('aria-pressed',String(x===btn)));renderCatalog()});
