function companion(){const pose=poses[state.twinPose]?state.twinPose:'idle';shell(`<span class="st-eyebrow">BEAR STUDIO / 3.2</span><h1>Мой Твин</h1><p class="st-lead">Твой спутник, твои правила. Теперь Твин — мультяшный мишка! Он двигается сам. Меняй цвет шерсти, одежду, движения и характер.</p><div class="st-card st-studio"><div class="st-studio-preview"><div class="st-studio-label"><span>ПРОСМОТР 360°</span><span id="twin-angle-value">0°</span></div><canvas id="twin-model" width="560" height="560" aria-label="Трёхмерная модель Твина. Вращение доступно с помощью ползунка и кнопок."></canvas><p class="st-drag-hint">← Проведи пальцем по персонажу →</p><div class="st-turn"><button type="button" class="st-outline" id="twin-left" aria-label="Повернуть влево">↶ 45°</button><button type="button" class="st-outline" id="twin-reset">Спереди</button><button type="button" class="st-outline" id="twin-right" aria-label="Повернуть вправо">45° ↷</button></div><label class="st-angle-label">Угол поворота<input id="twin-angle" type="range" min="0" max="359" step="1" value="${Math.round(Number(state.twinAngle)||0)}"></label><button type="button" class="st-button" id="twin-play" aria-pressed="true">Остановить анимацию</button><button type="button" class="st-outline" id="twin-auto" aria-pressed="true">Автодвижения: включены</button><button type="button" class="st-outline" id="twin-surprise">Случайное движение</button><p class="st-drag-hint">Твин анимируется автоматически, пока открыта студия. На телефоне используется облегчённая анимация.</p></div><div class="st-studio-controls"><span class="st-eyebrow">01 / ДВИЖЕНИЯ</span><h2>Позы и анимации</h2><div class="st-poses">${Object.entries(poses).map(([v,t],i)=>`<button type="button" data-pose="${v}" aria-pressed="${pose===v}"><span>${String(i+1).padStart(2,'0')}</span>${t}</button>`).join('')}</div><span class="st-eyebrow">02 / ВНЕШНИЙ ВИД</span><h2>Цвет шерсти мишки</h2><div class="st-color-palette">${twinPalette.map(c=>`<button type="button" data-twin-color="${c.id}" class="st-color-option" aria-label="${c.name}" aria-pressed="${(state.twinColor||'charcoal')===c.id}"><i style="background:${c.color}"></i><small>${c.name}${ownedItem(c.id)?'':' · ' + c.price + ' монет'}</small></button>`).join('')}</div><a class="st-outline" href="/shop">Магазин одежды и цветов →</a><span class="st-eyebrow">03 / ХАРАКТЕР</span><h2>Стиль общения</h2><form id="twin-form"><label>Имя персонажа<input name="twinName" maxlength="30" value="${esc(state.twinName||'Твин')}" required></label><label>Стиль общения<select name="twinStyle">${Object.entries(styles).map(([v,t])=>`<option value="${v}" ${((state.twinStyle||'friendly')===v)?'selected':''}>${t[0]}</option>`).join('')}</select></label><div class="st-twin-speech"><b id="twin-speech-name">${esc(state.twinName||'Твин')}</b><p id="twin-speech">${esc(talk(1,'companion-preview'))}</p></div><button class="st-button">Сохранить настройки</button><p id="twin-status" role="status"></p></form><a class="st-outline" href="/mentor">Попросить подсказку →</a></div></div>`);const form=document.querySelector('#twin-form');form.elements.twinStyle.onchange=e=>{document.querySelector('#twin-speech').textContent=styles[e.target.value][1]};form.elements.twinName.oninput=e=>{document.querySelector('#twin-speech-name').textContent=e.target.value||'Твин'};form.onsubmit=e=>{e.preventDefault();let f=new FormData(form);state.twinName=String(f.get('twinName')).trim()||'Твин';state.twinStyle=String(f.get('twinStyle'));document.querySelector('#twin-status').textContent=save()?'Настройки сохранены.':'Не удалось сохранить настройки.'};const studio=mountStudio(document.querySelector('#twin-model'),{angle:state.twinAngle,pose,color:twinColor(),outfit:equipped('outfit'),shoes:equipped('shoes'),hat:equipped('hat'),glasses:equipped('glasses'),autoplay:true,autoCycle:true},v=>{state.twinAngle=v.angle;state.twinPose=v.pose;save()});document.querySelectorAll('[data-twin-color]').forEach(b=>b.onclick=()=>{const id=b.dataset.twinColor;if(!ownedItem(id)){location.href='/shop';return}state.twinColor=id;if(save()){studio.setAppearance({color:twinColor()});document.querySelectorAll('[data-twin-color]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.twinColor===id)))}})}
