const gameState=(z,n)=>{z.games ||= {};return z.games[n] ||= {choice:null,order:[],revealed:false};};
function miniGame(c,l,z,n,card){const g=gameState(z,n);let inside='',ready=false;const title=card.kind==='sequence'?'Собери правильный порядок':card.kind==='verify'?'Верно или неверно?':'Вспомни без подсказки';
 if(card.kind==='verify'){const yes=card.pick===card.q.correct,checked=g.choice!==null,correct=checked&&g.choice===yes;ready=checked;inside=`<h2>${esc(card.q.question)}</h2><div class="st-game-proposal">${esc(card.q.options[card.pick])}</div><div class="st-game-choices">${[true,false].map(v=>`<button type="button" class="st-game-choice ${checked&&v===yes?'correct':checked&&v===g.choice?'wrong':''}" data-mini-verify="${v}" ${checked?'disabled':''}>${icon(v?'check':'flag',22)} ${v?'Верно':'Неверно'}</button>`).join('')}</div>${checked?`<div class="st-game-result ${correct?'good':'bad'}"><b>${correct?'Точно!':'Разберём ответ'}</b><p>${esc(card.q.explanation)}</p></div>`:''}`}
 else if(card.kind==='sequence'){const ids=card.steps.map((_,i)=>i),shuffled=[...ids.slice(1).reverse(),0],complete=g.order.length===ids.length,correct=complete&&g.order.every((v,i)=>v===i);ready=correct;inside=`<h2>${esc(card.title)}</h2><p>Нажимай на блоки в правильной последовательности.</p><div class="st-game-order">${ids.map((_,i)=>`<div class="st-game-slot"><span>${i+1}</span>${g.order[i]===undefined?'<em>Выбери шаг</em>':`<b>${esc(card.steps[g.order[i]])}</b>`}</div>`).join('')}</div><div class="st-game-pool">${shuffled.filter(i=>!g.order.includes(i)).map(i=>`<button class="st-game-token" data-mini-order="${i}">${esc(card.steps[i])}</button>`).join('')}</div>${g.order.length&&!correct?'<button class="st-outline" id="mini-reset">Начать заново</button>':''}${complete?`<div class="st-game-result ${correct?'good':'bad'}"><b>${correct?'Порядок правильный!':'Не совсем. Попробуй другой порядок.'}</b></div>`:''}`}
 else {ready=g.revealed;inside=`<div class="st-flash-card"><small>ВОПРОС</small><h2>${esc(card.q.question)}</h2><p>${g.revealed?'':'Сформулируй ответ своими словами, прежде чем перевернуть карточку.'}</p>${g.revealed?`<div class="st-flash-answer"><small>ОТВЕТ</small><b>${esc(card.q.options[card.q.correct])}</b><p>${esc(card.q.explanation)}</p></div>`:'<button type="button" class="st-outline" id="mini-reveal">Показать ответ</button>'}</div>`}
 return {ready,content:`<div class="st-study-block st-mini-game ${card.kind}" style="--world-h:${worldTheme(c.id)[0]}"><span class="st-study-label">${card.kind==='recall'?'ФЛЕШ-КАРТОЧКА':'МИНИ-ИГРА'}</span><h1>${title}</h1>${inside}<small class="st-game-note">Разминка без штрафов и дополнительных наград.</small></div>${lessonBuddy(ready?'cheer':'think',ready?'Хорошая разминка. Теперь двигайся дальше.':card.kind==='sequence'?'У каждого шага есть своё место.':card.kind==='recall'?'Попробуй вспомнить, не заглядывая в ответ.':'Сравни утверждение с тем, что уже изучили.')}`};
}
const theoryLine=(n,style)=>{const lines={direct:['Запомни ключевой принцип.','Проверь, как это работает.','Переходим к следующей идее.'],gentle:['Остановись на главной мысли.','Можно перечитать этот шаг в своём темпе.','Представь, где тебе пригодится эта идея.'],coach:['Фокус на главной мысли!','Ещё один шаг к цели.','Попробуй объяснить это без подсказок.'],mentor:['Какой принцип здесь лежит в основе?','Свяжи эту мысль с предыдущей.','В каком случае это правило не сработает?'],playful:['Новый фрагмент карты открыт!','Собираем знания по кусочкам.','Ещё одна деталь в твоём арсенале.'],minimalist:['Главное правило.','Пример применения.','Дальше.']};const common=['Поймай главную мысль этого шага.','Представь, где это пригодится на практике.','Свяжи эту идею с тем, что уже знаешь.','Попробуй объяснить это своими словами.','Ещё один кусочек темы на месте.','Подумай, какой пример ты бы привёл.'];const set=lines[style]||common;return set[(n-1)%set.length]};
function studyCard(c,l,d,z,cards){const n=z.readStep||0,total=cards.length+1,card=cards[n-1];let content,ready=true;
 if(card&&['verify','sequence','recall'].includes(card.kind)){const game=miniGame(c,l,z,n,card);content=game.content;ready=game.ready;}
 else if(!card){content=`<div class="st-study-hero"><span class="st-study-label">${esc(c.title)} · ${l.minutes} мин</span>${worldArt(c.id,c.symbol)}<h1>${esc(l.title)}</h1>${d.description?`<p>${esc(d.description)}</p>`:''}</div>${lessonBuddy('hello',talk(1,`lesson-intro-${c.id}-${l.id}`))}<div class="st-study-plan"><span><b>${cards.length}</b> учебных шагов</span><span><b>${l.quiz.length}</b> вопросов</span><span>${gem()} <b>Сундук</b> в финале</span></div>`}
 else if(card.kind==='theory'){content=`<div class="st-study-block st-theory-variant v${n%3}" style="--world-h:${worldTheme(c.id)[0]}"><span class="st-study-label">ТЕОРИЯ${card.parts>1?` · ${card.part}/${card.parts}`:''}</span><div class="st-study-symbol">${icon('learn',30)}</div><h1>${esc(card.title)}</h1><p class="st-study-copy">${esc(card.text)}</p></div>${lessonBuddy(n%3===0?'think':'idle',theoryLine(n,state.twinStyle))}`}
 else if(card.kind==='example'){const ex=card.example;content=`<div class="st-study-block"><span class="st-study-label">ПРИМЕР</span><h1>${esc(card.title)}</h1>${ex.bad?`<div class="st-study-example weak"><span>Исходный вариант</span><p>${esc(ex.bad)}</p></div>`:''}<div class="st-study-example strong"><span>Пример решения</span><p>${esc(ex.good)}</p></div>${ex.why?`<details class="st-study-explain"><summary>Почему это работает?</summary><p>${esc(ex.why)}</p></details>`:''}</div>${lessonBuddy('think',talk(2,`example-${c.id}-${l.id}-${n}`))}`}
 else {content=`<div class="st-study-block"><span class="st-study-label">ПРИМЕР КОДА</span><h1>${esc(card.title)}</h1><div class="st-study-code"><div><i></i><i></i><i></i><span>${esc(c.symbol)}</span></div><pre>${esc(card.code)}</pre></div><p class="st-study-note">Рассмотри пример, затем проверь понимание в вопросах.</p></div>${lessonBuddy('think',talk(2,`example-${c.id}-${l.id}-${n}`))}`}
 return `<div class="st-study-screen"><div class="st-study-count"><span>${n===0?'ЗНАКОМСТВО':card&&['verify','sequence','recall'].includes(card.kind)?'МИНИ-ПРАКТИКА':'ИЗУЧАЕМ ТЕМУ'}</span><b>${n+1} / ${total}</b></div><div class="st-study-dots" aria-label="Шаг ${n+1} из ${total}">${Array.from({length:total},(_,j)=>`<i class="${j<n?'past':j===n?'current':''}"></i>`).join('')}</div>${content}<div class="st-study-actions">${n>0?`<button class="st-outline st-study-back" id="study-back" aria-label="Предыдущий шаг">←</button>`:''}<button class="st-button" id="${n===cards.length?'lesson-start':'study-next'}" ${ready?'':'disabled'}>${n===cards.length?'К вопросам':n===0?'Начать урок':'Продолжить'} ${icon('arrow',19)}</button></div></div>`;
}
let lessonSession=null;
function lesson(c,l){const d=details(c,l);if(!d){shell('<h1>Урок не найден</h1><a class="st-button" href="/courses">К курсам</a>');return}const all=list(c),i=all.findIndex(x=>x.id===l.id),isAI=!!c.legacy,criteria=isAI?d.checklist:d.criteria,task=isAI?d.practice.task:d.task,qs=l.quiz;let saved=isAI?getAI().answers[l.id]:getTracks().enrollments[c.id]?.lessons[l.id];if(!lessonSession)lessonSession={stage:rewardFor(c,l).finished&&!rewardFor(c,l).chest&&done(c,l)?3:0,step:0,choices:[],answer:-1,checked:false,score:0,draft:saved?.draft||'',checks:saved?.checks||[],newCoins:false,newFinish:false};const z=lessonSession, cards=lessonCards(c,d,l);
function storeDraft(finish=false){const now=new Date().toISOString();if(isAI){const p=getAI(),a=p.answers[l.id]||{};p.answers[l.id]={...a,draft:z.draft,checks:z.checks,updatedAt:now,...(finish?{submittedDraft:z.draft,submittedAt:now}:{})};if(finish){p.quizzes[l.id]=[...(p.quizzes[l.id]||[]),{choices:z.choices,score:z.score,total:qs.length,at:now}];p.completed=[...new Set([...p.completed,+l.id])].sort((a,b)=>a-b);p.activityDates=[...new Set([...p.activityDates,day(new Date())])]}write(progressKey,p)}else{const p=getTracks();const t=p.enrollments[c.id]||{startedAt:now,lessons:{}};t.lessons[l.id]={...t.lessons[l.id],draft:z.draft,checks:z.checks,...(finish?{submitted:z.draft,submittedAt:now,quizPassed:true,choice:z.choices[0],completedAt:now}:{})};p.enrollments[c.id]=t;write(trackKey,p)}if(finish){state.days=[...new Set([...state.days,day(new Date())])];save()}}
let body=`<div class="st-quick-head"><a class="st-back" href="/learn">← Карта</a><span>УРОК ${i+1} ИЗ ${all.length}</span><span>${esc(c.symbol)}</span></div><div class="st-meter st-quick-meter"><i style="width:${z.stage===0?Math.round(5+30*(z.readStep||0)/Math.max(1,cards.length)):z.stage===1?Math.round(35+40*z.step/Math.max(1,qs.length)):z.stage===2?80:100}%"></i></div>`;
if(z.stage===0){body+=studyCard(c,l,d,z,cards)}
else if(z.stage===1){const q=qs[z.step];if(q){body+=`<div class="st-card st-quiz"><span class="st-eyebrow">ВОПРОС ${z.step+1} / ${qs.length}</span>${lessonBuddy(z.checked?(z.answer===q.correct?'cheer':'think'):'think',talk(z.checked?(z.answer===q.correct?3:4):2,`quiz-${c.id}-${l.id}-${z.step}-${z.answer}`))}<h1>${esc(q.question)}</h1><div class="st-options">${q.options.map((o,j)=>`<button class="st-option ${z.answer===j?'chosen':''} ${z.checked&&j===q.correct?'correct':''} ${z.checked&&z.answer===j&&j!==q.correct?'wrong':''}" data-option="${j}" ${z.checked?'disabled':''}><span>${String.fromCharCode(65+j)}</span>${esc(o)}</button>`).join('')}</div>${z.checked?`<div class="st-feedback ${z.answer===q.correct?'good':'bad'}"><b>${esc(talk(z.answer===q.correct?3:4,`feedback-${c.id}-${l.id}-${z.step}-${z.answer}`))}</b><p>${esc(q.explanation)}</p>${z.newCoins?`<div class="st-loot st-loot-pop">${coin()} <b>+5 монет</b></div>`:z.answer===q.correct?'<small>Награда за этот вопрос уже получена.</small>':''}</div><button class="st-button" id="lesson-next">Продолжить</button>`:`<button class="st-button" id="lesson-check" ${z.answer<0?'disabled':''}>Проверить</button>`}</div>`}else{body+=`<div class="st-card st-results"><h1>${z.score===qs.length?'Отличный результат!':'Давай повторим'}</h1><p>${z.score} из ${qs.length} правильных ответов</p><button class="st-button" id="lesson-retry">${z.score===qs.length?'Перейти к практике':'Повторить тест'}</button></div>`}}
else if(z.stage===2){body+=`<div class="st-card st-lesson"><span class="st-eyebrow">ПРАКТИКА</span><h1>${esc(isAI?d.practice.title:'Примени навык')}</h1>${lessonBuddy('hello',talk(5,`practice-${c.id}-${l.id}`)+' Проверь свою работу по чек-листу.')}<p>${esc(task)}</p>${isAI&&d.practice.steps?`<ol>${d.practice.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}<label>Твой ответ<textarea id="lesson-draft" rows="6" maxlength="12000" placeholder="Напиши решение…">${esc(z.draft)}</textarea></label><h3>Самопроверка</h3><div class="st-checklist">${criteria.map((x,j)=>`<label><input type="checkbox" data-criterion="${j}" ${z.checks.includes(j)?'checked':''}>${esc(x)}</label>`).join('')}</div><p>Открытый ответ проверяется по чек-листу самостоятельно.</p><button class="st-button" id="lesson-finish">Завершить урок ${icon('check',19)}</button><p id="lesson-msg" role="status"></p></div>`}
else{const next=all[i+1];body+=`<div class="st-card st-results">${icon('star',52)}<h1>Урок завершён!</h1><h2>${z.earned?'+20 XP':'Урок уже пройден'}</h2>${lessonBuddy('victory',talk(3,`finish-${c.id}-${l.id}`))}${z.newFinish?`<div class="st-loot st-loot-pop">${coin()} <b>+10</b> ${gem()} <b>+2</b></div>`:''}<p>Твой прогресс сохранён.</p>${chestCard(c,l,z)}<a class="st-button" href="${next?href(c,next):'/learn'}">${next?'Следующий урок':'Вернуться к карте'} ${icon('arrow',18)}</a><a class="st-outline" href="/learn">Учебная карта</a></div>`}
shell(`<div class="st-quick st-learning-flow">${body}</div>`);const again=()=>{lesson(c,l);window.scrollTo(0,0)};if(z.stage===0){const n=z.readStep||0,g=gameState(z,n);document.querySelectorAll('[data-mini-verify]').forEach(b=>b.onclick=()=>{if(g.choice===null){g.choice=b.dataset.miniVerify==='true';const card=cards[n-1];sound(g.choice===(card.pick===card.q.correct)?'correct':'wrong');lesson(c,l)}});document.querySelectorAll('[data-mini-order]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.miniOrder);if(!g.order.includes(i)){g.order.push(i);const card=cards[n-1];if(g.order.length===card.steps.length)sound(g.order.every((v,j)=>v===j)?'correct':'wrong');lesson(c,l)}});document.querySelector('#mini-reset')?.addEventListener('click',()=>{g.order=[];lesson(c,l)});document.querySelector('#mini-reveal')?.addEventListener('click',()=>{g.revealed=true;sound('flip');lesson(c,l)})}document.querySelector('#study-next')?.addEventListener('click',()=>{z.readStep=Math.min(cards.length,(z.readStep||0)+1);again()});document.querySelector('#study-back')?.addEventListener('click',()=>{z.readStep=Math.max(0,(z.readStep||0)-1);again()});document.querySelector('#lesson-start')?.addEventListener('click',()=>{z.stage=qs.length?1:2;again()});document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{z.answer=+b.dataset.option;lesson(c,l)});document.querySelector('#lesson-check')?.addEventListener('click',()=>{if(z.answer<0||z.checked)return;z.checked=true;z.choices[z.step]=z.answer;if(z.answer===qs[z.step].correct){z.score++;z.newCoins=grant(c,l,'answer',z.step);sound(z.newCoins?'coin':'correct')}else{z.newCoins=false;sound('wrong')}lesson(c,l)});document.querySelector('#lesson-next')?.addEventListener('click',()=>{z.step++;z.checked=false;z.newCoins=false;z.answer=-1;again()});document.querySelector('#lesson-retry')?.addEventListener('click',()=>{if(z.score===qs.length)z.stage=2;else{z.step=0;z.score=0;z.choices=[];z.answer=-1;z.checked=false}again()});document.querySelector('#lesson-draft')?.addEventListener('input',e=>{z.draft=e.target.value;storeDraft()});document.querySelectorAll('[data-criterion]').forEach(x=>x.onchange=()=>{z.checks=[...document.querySelectorAll('[data-criterion]:checked')].map(x=>+x.dataset.criterion);storeDraft()});document.querySelector('#lesson-finish')?.addEventListener('click',()=>{let min=isAI?d.practice.minLength:1;if(z.draft.trim().length<min||z.checks.length!==criteria.length){document.querySelector('#lesson-msg').textContent=`Заполни ответ (минимум ${min} символов) и отметь все критерии.`;return}z.earned=!done(c,l);storeDraft(true);z.newFinish=z.earned&&grant(c,l,'finish');sound('finish');z.stage=3;again()});document.querySelector('#lesson-chest')?.addEventListener('click',()=>{if(!grant(c,l,'chest')){document.querySelector('#chest-status').textContent='Награду не удалось сохранить. Попробуй ещё раз.';return}z.newFinish=false;sound('chest');lesson(c,l);const opened=document.querySelector('.st-chest');opened?.classList.add('just-opened');opened?.scrollIntoView({block:'center',behavior:'instant'})})}
function render(){const match=path.match(/^\/lesson\/(\d+)$/)||path.match(/^\/courses\/([^/]+)\/lesson\/([^/]+)$/);if(match){const c=courses.find(x=>x.id===(match.length===2?'ai':match[1]));const l=c&&list(c).find(x=>x.id===match[match.length-1]);if(l){state.course=c.id;save();lesson(c,l);return}}const cm=path.match(/^\/courses\/([^/]+)$/);if(cm&&courses.some(x=>x.id===cm[1])){state.course=cm[1];save();home();return}if(path==='/shop')shop();else if(path==='/profile')profile();else if(path==='/quick')quick();else if(path==='/courses')catalog();else if(path==='/companion')companion();else if(path==='/mentor')mentor();else if(path==='/progress'||path==='/dashboard')progress();else if(path==='/practice')practiceList();else home()}
installAudio();render();window.addEventListener('pageshow',e=>{if(e.persisted){state=read(key,state);render()}});
